shellCommands.command:
/bin/bash -lc "node --input-type=module <<'JS'
import assert from 'node:assert/strict'

const base = 'http://127.0.0.1:3100'
const cases = [
  ['/products/lamp?currency=EUR', 'Brass lamp', 'EUR 110.40', 'Stone vase'],
  ['/products/lamp?currency=EUR', 'Brass lamp', 'EUR 110.40', 'Stone vase'],
  ['/products/lamp', 'Brass lamp', 'USD 120.00', 'Stone vase'],
  ['/products/vase?currency=EUR', 'Stone vase', 'EUR 73.60', 'Brass lamp'],
  ['/products/vase?currency=USD', 'Stone vase', 'USD 80.00', 'Brass lamp'],
  ['/products/lamp?currency=EUR', 'Brass lamp', 'EUR 110.40', 'Stone vase'],
  ['/products/lamp?currency=EUR&currency=USD', 'Brass lamp', 'EUR 110.40', 'Stone vase'],
]
for (const [path, name, price, related] of cases) {
  const start = performance.now()
  const response = await fetch(base + path)
  assert.equal(response.status, 200)
  let html = ''
  const events = {}
  const decoder = new TextDecoder()
  for await (const chunk of response.body) {
    html += decoder.decode(chunk, { stream: true })
    for (const [key, marker] of [
      ['frame', 'Signal Shop collection'],
      ['loading', 'Loading product details...'],
      ['product', "'`<h1>${name}</h1><p>${price}</p>`],
      ['"'relatedLoading', 'Loading related products...'],
      ['related', "'`<p>${related}</p>`],
    ]) {
      if (html.includes(marker) && events[key] === undefined) events[key] = performance.now() - start
    }
  }
  for (const key of ['"'frame', 'loading', 'product', 'relatedLoading', 'related']) assert.ok(events[key] "'!== undefined, `${path}: missing ${key}`)
  assert.ok(events.frame < events.product, `${path}: frame must arrive before product`)
  assert.ok(events.product < events.related, `${path}: details must arrive before related products`)
  assert.ok(events.relatedLoading < events.related, `${path}: related fallback must arrive before related products`)
  console.log(JSON.stringify({ path, ms: Object.fromEntries(Object.entries(events).map(([k, v]) => [k, Math.round(v)])) }))
}
const missing = await fetch(base + '"'/products/missing?currency=EUR')
const missingHtml = await missing.text()
assert.match(missingHtml, /This page could not be found/)
assert.match(missingHtml, /name=\"robots\" content=\"noindex\"/)
console.log('Missing product: not-found UI and noindex verified')
const home = await fetch(base)
assert.equal(home.status, 200)
assert.match(await home.text(), /href=\"\\/products\\/lamp\\?currency=EUR\"/)
console.log('Home product link verified')
JS"
